arguments.new:
// gussets: hull wedges clear of the phone groove (groove ends at |x|=42)
for (sx = [-1,1]) {
    x0 = (sx > 0) ? 42 : -45;
    hull() {
        translate([x0, -11, 28]) cube([3,2,2]);
        translate([x0, 2, 28]) cube([3,2,2]);
        translate([x0, -11, 46]) cube([3,2,2]);
    }
}

arguments.old:
// gussets: hull wedges outside the phone groove (groove ends at |x|=42)
for (sx = [-1,1]) {
    x0 = (sx > 0) ? 41 : -45;
    hull() {
        translate([x0, -11, 28]) cube([4,2,2]);
        translate([x0, 2, 28]) cube([4,2,2]);
        translate([x0, -11, 46]) cube([4,2,2]);
    }
}
